// StackRightPickList.ts
// STAND-IN FOR BARCODE SCAN. A real picker's Lens would read the case's barcode when it is
// picked up. For the preview, the order is fixed: 31 cases of real store freight (sacks, cartons,
// shrink-wrapped tin trays, a long carton) in the warehouse system's heaviest-first sequence
// (5 layers). The learner should replace these lines with real order lines.
//
// Owns: the order (case data: name, weight, class, real size in cm, shape, colour, turned flag)
// and the LOAD PLAN, which is generated in code from the case sizes (not hand-placed): each layer
// is row (shelf) packed - cases in order, left to right while a row fits the 116.5 cm pallet, a
// new row nearer the user when it doesn't, row depth = deepest case in it, every row centred in x
// and the layer centred in z. Also the plan checks (overlaps, level layers, crossing joints).
// Pure data/logic, no scene access.
// Must not: touch the scene, hold game state.
//
// Case sizes are W (x) x H (y) x D (z) in cm, in the case's own frame. Plan positions are in
// Pallet-local cm: x right, z toward the user (near edge = +z), y up from the floor.
// Pallet deck top is at y = 15.

/** How the case is drawn: carton (box), sack (soft bag), tray (tins in a shrink-wrapped tray), long (112 cm carton). */
export type CaseShape = "carton" | "sack" | "tray" | "long"

export interface CaseSpec {
  key: string // used in scene object names, e.g. Case_03_PetFood
  name: string // printed on the case
  kg: number
  fragile: boolean // true = crushable, goes on top
  layer: number // 1..5
  size: vec3 // W x H x D, cm (case frame)
  shape: CaseShape
  turned: boolean // placed turned 90 degrees about up (case W runs along pallet z)
  color: vec4 // bright, light-saturated label colour (additive display: no dark colours)
}

export interface PlannedSlot {
  center: vec3 // Pallet-local centre of the case when placed
  layer: number // 1..5
  turned: boolean // true = turned 90 degrees about up (case W runs along pallet z)
  row: number // 0 = far row
  col: number // 0 = leftmost case in the row
}

export const PALLET_SIZE_CM = new vec3(116.5, 15, 116.5)
export const PALLET_DECK_Y = 15
export const HEIGHT_LIMIT_CM = 180

interface OrderLine {key: string, name: string, kg: number, fragile: boolean, layer: number,
  w: number, d: number, h: number, count: number, shape: CaseShape, turned: boolean, color: vec4}

// The order, sizes W x D x H in cm, already heaviest first. Every case in a layer has the same H,
// so each layer finishes level. Layers 3 and 4 are turned so their joints cross the layer below.
const ORDER_LINES: OrderLine[] = [
  {key: "PetFood", name: "PET FOOD 20kg", kg: 20, fragile: false, layer: 1, w: 55, d: 37, h: 14, count: 6, shape: "sack", turned: false, color: new vec4(1.0, 0.62, 0.5, 1)},
  {key: "Laundry", name: "LAUNDRY 4x4L", kg: 17, fragile: false, layer: 2, w: 38, d: 58, h: 30, count: 6, shape: "carton", turned: false, color: new vec4(0.6, 0.55, 1.0, 1)},
  {key: "Water", name: "WATER 24", kg: 14, fragile: false, layer: 3, w: 38, d: 58, h: 25, count: 4, shape: "carton", turned: true, color: new vec4(0.35, 0.75, 1.0, 1)},
  {key: "Juice", name: "JUICE 12x1L", kg: 12, fragile: false, layer: 3, w: 38, d: 29, h: 25, count: 4, shape: "carton", turned: true, color: new vec4(1.0, 0.7, 0.3, 1)},
  {key: "Tomatoes", name: "TINNED TOMATOES 2x24", kg: 10, fragile: false, layer: 4, w: 57, d: 38, h: 13, count: 6, shape: "tray", turned: true, color: new vec4(1.0, 0.42, 0.42, 1)},
  {key: "Bread", name: "BREAD", kg: 4, fragile: true, layer: 5, w: 56, d: 45, h: 30, count: 2, shape: "carton", turned: false, color: new vec4(1.0, 0.85, 0.45, 1)},
  {key: "PaperTowel", name: "PAPER TOWEL 12", kg: 3, fragile: false, layer: 5, w: 112, d: 25, h: 30, count: 1, shape: "long", turned: false, color: new vec4(0.8, 0.9, 1.0, 1)},
  {key: "Chips", name: "CHIPS", kg: 2, fragile: true, layer: 5, w: 56, d: 45, h: 30, count: 2, shape: "carton", turned: false, color: new vec4(0.5, 1.0, 0.6, 1)},
]

// Shown on the pallet when a layer is finished: true for this plan (see the joint check below).
const LAYER_DONE_NOTES: {[layer: number]: string} = {
  1: "Cartons next: their joints miss the sack seams.",
  2: "Next layer turns 90° so the joints cross.",
  3: "Flat trays next: keep the top level.",
  4: "Light and fragile last: bread, towels, chips.",
}

function buildOrder(): CaseSpec[] {
  const out: CaseSpec[] = []
  for (const l of ORDER_LINES) {
    for (let k = 0; k < l.count; k++) {
      out.push({key: l.key, name: l.name, kg: l.kg, fragile: l.fragile, layer: l.layer,
        size: new vec3(l.w, l.h, l.d), shape: l.shape, turned: l.turned, color: l.color})
    }
  }
  return out
}

export const ORDER: CaseSpec[] = buildOrder()
export const LAYER_COUNT = ORDER.reduce((m, c) => Math.max(m, c.layer), 0)

/** True when the layer's cases are placed turned 90 degrees (from the order data). */
export function isTurnedLayer(layer: number): boolean {
  for (const c of ORDER) if (c.layer === layer && c.turned) return true
  return false
}

/** Footprint on the pallet (x = across, z = depth) of a case in the planned orientation. */
export function footprint(spec: CaseSpec, turned: boolean): vec2 {
  return turned ? new vec2(spec.size.z, spec.size.x) : new vec2(spec.size.x, spec.size.z)
}

/** Ghost / placed size in pallet axes: the case size with x and z swapped when turned. */
export function plannedSize(spec: CaseSpec, turned: boolean): vec3 {
  return turned ? new vec3(spec.size.z, spec.size.y, spec.size.x) : spec.size
}

/**
 * Generates the slot plan for the whole order. For each layer: take its cases in order, each with
 * its footprint (turned when the line says so), fill a row left to right while it fits the pallet,
 * start a new row nearer the user when it doesn't (row depth = deepest case in it), centre each
 * row in x and the whole layer in z, and stack the layer on the previous layer's top. Prints an
 * error when a layer overflows the pallet or mixes case heights.
 */
export function buildPlan(order: CaseSpec[]): PlannedSlot[] {
  const plan: PlannedSlot[] = []
  const S = PALLET_SIZE_CM.x
  let bottom = PALLET_DECK_Y
  let i = 0
  while (i < order.length) {
    const layer = order[i].layer
    const start = i
    while (i < order.length && order[i].layer === layer) i++

    const rows: {items: number[], width: number, depth: number}[] = []
    for (let k = start; k < i; k++) {
      const fp = footprint(order[k], order[k].turned)
      let row = rows[rows.length - 1]
      if (!row || row.width + fp.x > S + 0.001) {
        row = {items: [], width: 0, depth: 0}
        rows.push(row)
      }
      row.items.push(k)
      row.width += fp.x
      row.depth = Math.max(row.depth, fp.y)
    }

    const height = order[start].size.y
    let depth = 0
    for (const r of rows) {
      depth += r.depth
      if (r.width > S + 0.001) print("[StackRightPickList] ERROR: layer " + layer + " row is " + r.width + " cm wide, pallet is " + S)
    }
    if (depth > S + 0.001) print("[StackRightPickList] ERROR: layer " + layer + " is " + depth + " cm deep, pallet is " + S)
    for (let k = start; k < i; k++) {
      if (Math.abs(order[k].size.y - height) > 0.001) {
        print("[StackRightPickList] ERROR: layer " + layer + " mixes heights (" + order[k].name + " is " + order[k].size.y + " cm, layer is " + height + " cm)")
      }
    }

    let z = -depth / 2
    rows.forEach((r, ri) => {
      let x = -r.width / 2
      r.items.forEach((k, ci) => {
        const fp = footprint(order[k], order[k].turned)
        plan.push({
          center: new vec3(x + fp.x / 2, bottom + order[k].size.y / 2, z + r.depth / 2),
          layer, turned: order[k].turned, row: ri, col: ci,
        })
        x += fp.x
      })
      z += r.depth
    })
    bottom += height
  }
  return plan
}

export const PLAN: PlannedSlot[] = buildPlan(ORDER)

/** Top of the finished stack above the floor (cm). */
export const STACK_HEIGHT_CM = PLAN.reduce((m, s, k) => Math.max(m, s.center.y + ORDER[k].size.y / 2), PALLET_DECK_Y)

/** Number of cases in each layer, index = layer. */
export function layerCaseCount(layer: number): number {
  let n = 0
  for (const c of ORDER) if (c.layer === layer) n++
  return n
}

/** True when case i is the last one of its layer in the order. */
export function isLastOfLayer(i: number): boolean {
  return i < ORDER.length && (i === ORDER.length - 1 || ORDER[i + 1].layer !== ORDER[i].layer)
}

export function ghostTagText(i: number): string {
  return "Layer " + ORDER[i].layer + " · " + (i + 1) + " of " + ORDER.length + " · " + ORDER[i].kg + " kg"
}

export function layerDoneText(layer: number): string {
  return "Layer " + layer + " done.\n" + (LAYER_DONE_NOTES[layer] || "Start the next layer on the ghost.")
}

// ---------------------------------------------------------------------------------------------
// Plan checks (used by the self-test, the LEAF scenarios and the report)
// ---------------------------------------------------------------------------------------------
interface Rect2 {x0: number, x1: number, z0: number, z1: number}

function slotRect(k: number): Rect2 {
  const fp = footprint(ORDER[k], PLAN[k].turned)
  const c = PLAN[k].center
  return {x0: c.x - fp.x / 2, x1: c.x + fp.x / 2, z0: c.z - fp.y / 2, z1: c.z + fp.y / 2}
}

function layerSlots(layer: number): number[] {
  const out: number[] = []
  for (let k = 0; k < PLAN.length; k++) if (PLAN[k].layer === layer) out.push(k)
  return out
}

/** Pairs of cases in the same layer whose footprints overlap, e.g. "3/4". Empty = no overlaps. */
export function planOverlaps(): string[] {
  const out: string[] = []
  for (let a = 0; a < PLAN.length; a++) {
    for (let b = a + 1; b < PLAN.length; b++) {
      if (PLAN[a].layer !== PLAN[b].layer) continue
      const ra = slotRect(a), rb = slotRect(b)
      const ox = Math.min(ra.x1, rb.x1) - Math.max(ra.x0, rb.x0)
      const oz = Math.min(ra.z1, rb.z1) - Math.max(ra.z0, rb.z0)
      if (ox > 0.01 && oz > 0.01) out.push(a + "/" + b)
    }
  }
  return out
}

/** Cases whose footprint reaches past the pallet edge. Empty = all inside. */
export function planOutsidePallet(): number[] {
  const h = PALLET_SIZE_CM.x / 2 + 0.01
  const out: number[] = []
  for (let k = 0; k < PLAN.length; k++) {
    const r = slotRect(k)
    if (r.x0 < -h || r.x1 > h || r.z0 < -h || r.z1 > h) out.push(k)
  }
  return out
}

/** True when every case in the layer has its top at the same height. */
export function isLayerLevel(layer: number): boolean {
  const ks = layerSlots(layer)
  if (ks.length === 0) return false
  const top = PLAN[ks[0]].center.y + ORDER[ks[0]].size.y / 2
  for (const k of ks) if (Math.abs(PLAN[k].center.y + ORDER[k].size.y / 2 - top) > 0.01) return false
  return true
}

/** Number of different footprints (size in pallet axes) in the layer. */
export function layerFootprintCount(layer: number): number {
  const seen: string[] = []
  for (const k of layerSlots(layer)) {
    const fp = footprint(ORDER[k], PLAN[k].turned)
    const key = fp.x.toFixed(1) + "x" + fp.y.toFixed(1)
    if (seen.indexOf(key) < 0) seen.push(key)
  }
  return seen.length
}

/** A joint: where two neighbouring cases in a layer touch. axis "x" = a line x = at (running along z). */
export interface Joint {axis: "x" | "z", at: number, from: number, to: number}

export function layerJoints(layer: number): Joint[] {
  const ks = layerSlots(layer)
  const out: Joint[] = []
  for (const a of ks) {
    for (const b of ks) {
      if (a === b) continue
      const ra = slotRect(a), rb = slotRect(b)
      if (Math.abs(ra.x1 - rb.x0) < 0.01) {
        const from = Math.max(ra.z0, rb.z0), to = Math.min(ra.z1, rb.z1)
        if (to - from > 0.01) out.push({axis: "x", at: ra.x1, from, to})
      }
      if (Math.abs(ra.z1 - rb.z0) < 0.01) {
        const from = Math.max(ra.x0, rb.x0), to = Math.min(ra.x1, rb.x1)
        if (to - from > 0.01) out.push({axis: "z", at: ra.z1, from, to})
      }
    }
  }
  return out
}

/**
 * Joints of `upper` that run along a joint of the layer below (same line within 2 cm, sharing more
 * than 5 cm), e.g. "x=0 for 76 cm". Empty = every joint crosses the layer below.
 */
export function alignedJoints(upper: number): string[] {
  const out: string[] = []
  const lower = layerJoints(upper - 1)
  for (const u of layerJoints(upper)) {
    for (const l of lower) {
      if (u.axis !== l.axis || Math.abs(u.at - l.at) > 2) continue
      const shared = Math.min(u.to, l.to) - Math.max(u.from, l.from)
      if (shared > 5) {
        const s = u.axis + "=" + (Math.round(u.at * 10) / 10) + " for " + Math.round(shared) + " cm"
        if (out.indexOf(s) < 0) out.push(s)
      }
    }
  }
  return out
}

/** One line per layer: rows and footprints, for the log/report. */
export function describePlan(): string[] {
  const out: string[] = []
  for (let l = 1; l <= LAYER_COUNT; l++) {
    const rows: string[] = []
    for (const k of layerSlots(l)) {
      const fp = footprint(ORDER[k], PLAN[k].turned)
      const r = PLAN[k].row
      rows[r] = (rows[r] ? rows[r] + " + " : "") + ORDER[k].key + " " + fp.x + "x" + fp.y
    }
    const ks = layerSlots(l)
    out.push("layer " + l + (isTurnedLayer(l) ? " (turned)" : "") + ", top " + (PLAN[ks[0]].center.y + ORDER[ks[0]].size.y / 2) +
      " cm: " + rows.map((s, r) => "row " + r + " [" + s + "]").join(" | "))
  }
  return out
}

// StackRightGeometry.ts
// Owns: tiny helpers that build primitive box visuals (pallet, shelves, cartons, ghost, arrow)
// from one 1 cm box mesh + one unlit material that is cloned per box. These are the obvious
// placeholder visuals; swap the boxMesh / baseMaterial @inputs on the controller to upgrade.
// Scale always lives on the leaf "Visual" child, never on a node that owns a collider.
// Must not: hold game state or create text.

export class BoxFactory {
  constructor(private mesh: RenderMesh, private baseMaterial: Material) {}

  makeMaterial(color: vec4, translucent: boolean): Material {
    const mat = this.baseMaterial.clone()
    mat.mainPass.baseColor = color
    if (translucent) {
      mat.mainPass.blendMode = BlendMode.Normal
      mat.mainPass.depthWrite = false
    }
    return mat
  }

  /** Creates a child SceneObject with a box visual of `size` cm centred at `localPos` (`material` = share one). */
  makeBox(parent: SceneObject, name: string, size: vec3, localPos: vec3, color: vec4,
    translucent: boolean = false, material: Material = null): RenderMeshVisual {
    const so = global.scene.createSceneObject(name)
    so.setParent(parent)
    const t = so.getTransform()
    t.setLocalPosition(localPos)
    t.setLocalScale(size)
    const rmv = so.createComponent("Component.RenderMeshVisual") as RenderMeshVisual
    rmv.mesh = this.mesh
    rmv.mainMaterial = material || this.makeMaterial(color, translucent)
    return rmv
  }

  /** 12 thin bars outlining a box of `size` centred at the parent's origin. */
  makeWireBox(parent: SceneObject, name: string, size: vec3, thickness: number, color: vec4): SceneObject {
    const root = global.scene.createSceneObject(name)
    root.setParent(parent)
    const mat = this.makeMaterial(color, true)
    for (let i = 0; i < 12; i++) {
      const bar = global.scene.createSceneObject("Edge" + i)
      bar.setParent(root)
      const rmv = bar.createComponent("Component.RenderMeshVisual") as RenderMeshVisual
      rmv.mesh = this.mesh
      rmv.mainMaterial = mat
    }
    BoxFactory.layoutWireBox(root, size, thickness)
    return root
  }

  static layoutWireBox(root: SceneObject, size: vec3, th: number): void {
    const hx = size.x / 2, hy = size.y / 2, hz = size.z / 2
    const specs: [vec3, vec3][] = []
    for (const sy of [-1, 1]) for (const sz of [-1, 1]) specs.push([new vec3(0, sy * hy, sz * hz), new vec3(size.x + th, th, th)])
    for (const sx of [-1, 1]) for (const sz of [-1, 1]) specs.push([new vec3(sx * hx, 0, sz * hz), new vec3(th, size.y + th, th)])
    for (const sx of [-1, 1]) for (const sy of [-1, 1]) specs.push([new vec3(sx * hx, sy * hy, 0), new vec3(th, th, size.z + th)])
    for (let i = 0; i < 12 && i < root.getChildrenCount(); i++) {
      const t = root.getChild(i).getTransform()
      t.setLocalPosition(specs[i][0])
      t.setLocalScale(specs[i][1])
    }
  }
}

// ---------------------------------------------------------------------------------------------
// MeshBuilder shapes for the freight (built once, shared by every case of that shape)
// ---------------------------------------------------------------------------------------------
type V3 = [number, number, number]

/** Collects triangles and fixes their winding so each one faces `outward` (CCW from outside). */
class TriMesh {
  verts: number[] = []
  idx: number[] = []
  private n = 0

  vertex(p: V3, nrm: V3): number {
    this.verts.push(p[0], p[1], p[2], nrm[0], nrm[1], nrm[2], 0, 0)
    return this.n++
  }

  tri(a: number, b: number, c: number, outward: V3): void {
    const P = (k: number): V3 => [this.verts[k * 8], this.verts[k * 8 + 1], this.verts[k * 8 + 2]]
    const pa = P(a), pb = P(b), pc = P(c)
    const u: V3 = [pb[0] - pa[0], pb[1] - pa[1], pb[2] - pa[2]]
    const v: V3 = [pc[0] - pa[0], pc[1] - pa[1], pc[2] - pa[2]]
    const cx = u[1] * v[2] - u[2] * v[1], cy = u[2] * v[0] - u[0] * v[2], cz = u[0] * v[1] - u[1] * v[0]
    if (cx * outward[0] + cy * outward[1] + cz * outward[2] >= 0) this.idx.push(a, b, c)
    else this.idx.push(a, c, b)
  }

  build(): RenderMesh {
    const mb = new MeshBuilder([
      {name: "position", components: 3},
      {name: "normal", components: 3},
      {name: "texture0", components: 2},
    ])
    mb.topology = MeshTopology.Triangles
    mb.indexType = MeshIndexType.UInt16
    mb.appendVerticesInterleaved(this.verts)
    mb.appendIndices(this.idx)
    mb.updateMesh()
    return mb.getMesh()
  }
}

function spow(v: number, e: number): number {
  return (v < 0 ? -1 : 1) * Math.pow(Math.abs(v), e)
}

export class ShapeMeshes {
  private static pillow: RenderMesh = null
  private static tinBodies: RenderMesh = null
  private static tinLids: RenderMesh = null

  /**
   * Soft sack: a 1 cm superellipsoid (boxy in plan, rounded top and bottom), centred on the
   * origin. Scale it to the sack size like the 1 cm box mesh.
   */
  static pillowMesh(): RenderMesh {
    if (ShapeMeshes.pillow) return ShapeMeshes.pillow
    const m = new TriMesh()
    const LAT = 10, LON = 28, eV = 0.55, eH = 0.3
    const ring: number[][] = []
    for (let i = 0; i <= LAT; i++) {
      const th = -Math.PI / 2 + Math.PI * i / LAT
      const row: number[] = []
      for (let j = 0; j < LON; j++) {
        const ph = 2 * Math.PI * j / LON
        const r = spow(Math.cos(th), eV)
        const p: V3 = [0.5 * r * spow(Math.cos(ph), eH), 0.5 * spow(Math.sin(th), eV), 0.5 * r * spow(Math.sin(ph), eH)]
        const len = Math.max(1e-6, Math.sqrt(p[0] * p[0] + p[1] * p[1] + p[2] * p[2]))
        row.push(m.vertex(p, [p[0] / len, p[1] / len, p[2] / len]))
      }
      ring.push(row)
    }
    const at = (k: number): V3 => [m.verts[k * 8], m.verts[k * 8 + 1], m.verts[k * 8 + 2]]
    for (let i = 0; i < LAT; i++) {
      for (let j = 0; j < LON; j++) {
        const a = ring[i][j], b = ring[i][(j + 1) % LON], c = ring[i + 1][(j + 1) % LON], d = ring[i + 1][j]
        const o = at(c), o2 = at(a)
        const out: V3 = [o[0] + o2[0], o[1] + o2[1], o[2] + o2[2]]
        m.tri(a, b, c, out)
        m.tri(a, c, d, out)
      }
    }
    ShapeMeshes.pillow = m.build()
    return ShapeMeshes.pillow
  }

  /**
   * Tins for a tray, in cm, centred on the origin in x/z with the tin bottoms at y = 0: a grid of
   * `cols` x `rows` short cylinders filling `areaX` x `areaZ`. Bodies and lids are separate meshes
   * so they can take different colours. Shared by every tray (all trays in the order are the same).
   */
  static tinMeshes(cols: number, rows: number, areaX: number, areaZ: number, height: number): RenderMesh[] {
    if (ShapeMeshes.tinBodies) return [ShapeMeshes.tinBodies, ShapeMeshes.tinLids]
    const SEG = 14
    const pitchX = areaX / cols, pitchZ = areaZ / rows
    const r = Math.min(pitchX, pitchZ) / 2 - 0.4
    const bodies = new TriMesh(), lids = new TriMesh()
    for (let cx = 0; cx < cols; cx++) {
      for (let cz = 0; cz < rows; cz++) {
        const ox = -areaX / 2 + pitchX * (cx + 0.5), oz = -areaZ / 2 + pitchZ * (cz + 0.5)
        const bot: number[] = [], top: number[] = [], lid: number[] = []
        for (let s = 0; s < SEG; s++) {
          const a = 2 * Math.PI * s / SEG
          const nx = Math.cos(a), nz = Math.sin(a)
          bot.push(bodies.vertex([ox + r * nx, 0, oz + r * nz], [nx, 0, nz]))
          top.push(bodies.vertex([ox + r * nx, height, oz + r * nz], [nx, 0, nz]))
          lid.push(lids.vertex([ox + (r - 0.3) * nx, height + 0.2, oz + (r - 0.3) * nz], [0, 1, 0]))
        }
        const centre = lids.vertex([ox, height + 0.2, oz], [0, 1, 0])
        for (let s = 0; s < SEG; s++) {
          const s2 = (s + 1) % SEG
          const am = 2 * Math.PI * (s + 0.5) / SEG
          const out: V3 = [Math.cos(am), 0, Math.sin(am)]
          bodies.tri(bot[s], bot[s2], top[s2], out)
          bodies.tri(bot[s], top[s2], top[s], out)
          lids.tri(centre, lid[s], lid[s2], [0, 1, 0])
        }
      }
    }
    ShapeMeshes.tinBodies = bodies.build()
    ShapeMeshes.tinLids = lids.build()
    return [ShapeMeshes.tinBodies, ShapeMeshes.tinLids]
  }
}

// StackRightController.ts
// Stack Right: pallet-building trainer. Owns ALL game state (case due now, placed count,
// mistakes, timer, pick-face queue) and the rules: ghost on grab (turned on the turned layers),
// snap within 15 cm with the planned rotation, dropped on the pallet but off the ghost ->
// slide back + red "overhang" / "gap" tip + mistake, released off the pallet -> slide back
// (no mistake), "layer done" note, completion card, reset, glow on the case due now,
// off-view arrow + chime, height-limit outline. Also builds the scenery: pallet, shelf bay and a
// ride-on electric pallet jack with its forks in the pallet (no physics, no rules).
//
// Expects (@input): the authored Pallet, ShelfBay, PickList root (cases are created at runtime
// under it; any authored children are reused for the first ones), Ghost, OffViewArrow, ResetPost
// SceneObjects; the four StackRightLabelUI panels (GhostTag, Counter, TipText, CompletionCard);
// the StackRightResetButtonUI; the 1 cm box mesh and unlit base material used for every
// placeholder visual.
//
// Pick face: only the next QUEUE_SIZE not-yet-placed cases are shown, on the lower shelf, the one
// due now in the slot nearest the pallet. The rest are disabled until they enter the queue. Only
// the case due now is interactable.
//
// Real SIK grab/release events and the LEAF test hooks (simulateGrab / simulateRelease) run
// through the same handleGrab / handleRelease code path.
// Must not: build UI text itself (labels live in the *UI.ts modules), or plan slots (PickList does).
import {Interactable} from "SpectaclesInteractionKit.lspkg/Components/Interaction/Interactable/Interactable"
import {InteractableManipulation} from "SpectaclesInteractionKit.lspkg/Components/Interaction/InteractableManipulation/InteractableManipulation"
import WorldCameraFinderProvider from "SpectaclesInteractionKit.lspkg/Providers/CameraProvider/WorldCameraFinderProvider"
import {
  ORDER, PLAN, CaseSpec, PALLET_SIZE_CM, PALLET_DECK_Y, HEIGHT_LIMIT_CM, LAYER_COUNT, STACK_HEIGHT_CM,
  footprint, plannedSize, ghostTagText, layerDoneText, isLastOfLayer,
} from "./StackRightPickList"
import {BoxFactory, ShapeMeshes} from "./StackRightGeometry"
import {StackRightLabelUI} from "./StackRightLabelUI"
import {StackRightResetButtonUI} from "./StackRightResetButtonUI"
import {StackRightCartonLabelUI} from "./StackRightCartonLabelUI"

const SFX_CHIME = requireAsset("../GeneratedSFX/StackRightChime.wav") as AudioTrackAsset
const SFX_SNAP = requireAsset("../GeneratedSFX/StackRightSnap.wav") as AudioTrackAsset
const SFX_MISTAKE = requireAsset("../GeneratedSFX/StackRightMistake.wav") as AudioTrackAsset
const SFX_COMPLETE = requireAsset("../GeneratedSFX/StackRightComplete.wav") as AudioTrackAsset

const CHIME_COOLDOWN_SEC = 6
const OFF_PALLET_MARGIN_CM = 5
/** A drop whose footprint hangs further than this over the pallet edge is an overhang. */
const OVERHANG_TOLERANCE_CM = 2
const QUEUE_SIZE = 4
/** Lower shelf of the bay (ShelfBay-local): top of the board, and the 4 queue slots along it. */
const SHELF_TOP_Y = 40
const QUEUE_FRONT_Z = 93 // slot nearest the pallet (and the user)
const QUEUE_PITCH_Z = -62 // each later queue slot is further along the shelf (deepest case is 58)
/** Shelf boards run from the front edge (facing the pallet) back 120 cm, so the 112 cm carton fits. */
const SHELF_FRONT_X = -30
const SHELF_DEPTH_X = 120
const SHELF_LENGTH_Z = 280

// Two lines (break at the sentence) so the tip stays narrower than the pallet in view.
export const TIP_OVERHANG = "Overhang.\nKeep it inside the edge."
export const TIP_GAP = "That leaves a gap.\nDrop it on the ghost."

interface CaseState {
  index: number
  spec: CaseSpec
  so: SceneObject
  home: vec3
  placed: boolean
  grabbed: boolean
  returning: boolean
  returnFrom: vec3
  returnT: number
  hovered: boolean
  interactable: Interactable
  manip: InteractableManipulation
  bodyMats: Material[] // lightened on hover; the shrink-wrap is not in here
  bodyColors: vec4[]
  glow: SceneObject
  glowMat: Material
}

@component
export class StackRightController extends BaseScriptComponent {
  @ui.label('<span style="color: #60A5FA;">StackRightController – pallet-building trainer rules + test API</span>')
  @ui.separator

  @ui.label('<span style="color: #60A5FA;">References</span>')
  @ui.group_start("References")
  @input
  @hint("Pallet root: on the floor, origin at the centre of its footprint")
  pallet: SceneObject
  @input
  @hint("Shelf bay root: on the floor to the user's right")
  shelfBay: SceneObject
  @input
  @hint("PickList (stand-in for barcode scan): cases are created under it at runtime, in order")
  pickList: SceneObject
  @input
  @hint("Ghost case root (child of Pallet)")
  ghost: SceneObject
  @input
  @hint("Arrow on the pallet edge that points at the case due now when it is out of view")
  offViewArrow: SceneObject
  @input
  @hint("Short post under the Reset button")
  resetPost: SceneObject
  @input
  @hint("Tag on the ghost: 'Layer N · K of 31 · kg'")
  ghostTag: StackRightLabelUI
  @input
  @hint("'Layer N · K / 31' counter on the pallet's near edge")
  counter: StackRightLabelUI
  @input
  @hint("Red tip (mistakes) / white note (layer done) shown on the pallet for a few seconds")
  tipText: StackRightLabelUI
  @input
  @hint("Completion card: cases, layers, height, time, mistakes, 'Wrap and label'")
  completionCard: StackRightLabelUI
  @input
  @hint("Reset pallet button")
  resetButton: StackRightResetButtonUI
  @input
  @hint("1 cm box mesh used for every placeholder visual")
  boxMesh: RenderMesh
  @input
  @hint("Unlit material cloned for every placeholder visual")
  baseMaterial: Material
  @ui.group_end

  @ui.separator
  @ui.label('<span style="color: #60A5FA;">Settings</span>')
  @ui.group_start("Settings")
  @input
  @hint("Release within this horizontal distance (cm) of the ghost to snap")
  @widget(new SliderWidget(5, 40, 1))
  snapDistanceCm: number = 15

  @input
  @hint("Mouse-friendly allowance: how far ABOVE the ghost (cm) a release still snaps. Below, the limit is snapDistanceCm.")
  @widget(new SliderWidget(0, 120, 1))
  dropHeightAllowanceCm: number = 60

  @input
  @hint("How long the red tip / layer note stays on the pallet (s)")
  @widget(new SliderWidget(1, 10, 0.5))
  tipDurationSec: number = 4

  @input
  @hint("Place the floor this far below the user's eyes at start (cm). The work area root (this object's parent) is moved to camera.y - eyeHeightCm.")
  @widget(new SliderWidget(100, 200, 1))
  eyeHeightCm: number = 150

  @input("vec4", "{0.6,1,1,0.3}")
  @hint("Ghost fill colour (pale cyan, about 30% fill)")
  @widget(new ColorWidget())
  ghostColor: vec4 = new vec4(0.6, 1, 1, 0.3)

  @input("vec4", "{1,1,0.55,0.35}")
  @hint("Soft glow around the case due now on the pick face")
  @widget(new ColorWidget())
  glowColor: vec4 = new vec4(1, 1, 0.55, 0.35)

  @input("vec4", "{1,0.35,0.35,1}")
  @hint("Tip text colour (bright red, not dark)")
  @widget(new ColorWidget())
  tipColor: vec4 = new vec4(1, 0.35, 0.35, 1)

  @input("vec4", "{1,1,1,1}")
  @hint("Layer-done note text colour")
  @widget(new ColorWidget())
  noteColor: vec4 = new vec4(1, 1, 1, 1)

  @input("vec4", "{0.85,0.95,1,0.7}")
  @hint("Height-limit outline colour (thin, pale)")
  @widget(new ColorWidget())
  heightLimitColor: vec4 = new vec4(0.85, 0.95, 1, 0.7)
  @ui.group_end

  @ui.separator
  @ui.label('<span style="color: #60A5FA;">Debug</span>')
  @ui.group_start("Debug")
  @input
  @hint("Print grab/release decisions to the log")
  debugLogs: boolean = false
  @ui.group_end

  // ---- state (single owner) ----
  private cases: CaseState[] = []
  private nextIndex = 0
  private placedCount = 0
  private mistakes = 0
  private overhangMistakes = 0
  private gapMistakes = 0
  private complete = false
  private grabbedIndex = -1
  private startTime = -1
  private finishTime = -1
  private tipHideAt = -1
  private tipKind = "" // "" | "overhang" | "gap" | "layer"
  private ghostTagString = ""
  private tipString = ""
  private completionString = ""
  private arrowVisible = false
  private nextInView = true
  private lastChimeAt = -100
  private wasOutOfView = false

  private factory: BoxFactory
  private ghostFill: SceneObject
  private ghostWire: SceneObject
  private heightLimit: SceneObject
  private palletT: Transform
  private returnDuration = 0.6
  private audio: {[k: string]: AudioComponent} = {}
  private ready = false

  onAwake(): void {
    if (!this.validateRefs()) return
    this.factory = new BoxFactory(this.boxMesh, this.baseMaterial)
    this.palletT = this.pallet.getTransform()
    this.alignFloorToCamera()
    this.buildPalletVisual()
    this.buildPalletJackVisual()
    this.buildShelfVisual()
    this.buildResetPostVisual()
    this.buildHeightLimit()
    this.buildGhost()
    this.buildArrow()
    this.buildCases()
    this.buildAudio()

    this.createEvent("OnStartEvent").bind(() => this.onStart())
    this.createEvent("UpdateEvent").bind(() => this.onUpdate())
  }

  private onStart(): void {
    for (const c of this.cases) {
      const i = c.index
      c.manip.onManipulationStart.add(() => this.handleGrab(i))
      c.manip.onManipulationEnd.add(() => this.handleRelease(i, c.so.getTransform().getWorldPosition()))
      c.interactable.onHoverEnter.add(() => this.setHover(i, true))
      c.interactable.onHoverExit.add(() => this.setHover(i, false))
    }
    this.resetButton.onReset.add(() => this.reset())
    this.ready = true
    this.reset()
    const cam = WorldCameraFinderProvider.getInstance()
    print("[StackRight] ready. " + this.cases.length + " cases, " + LAYER_COUNT + " layers, stack " + STACK_HEIGHT_CM +
      " cm. camera = " + cam.getTransform().getWorldPosition() + " pallet = " + this.getPalletWorldPosition() +
      " shelf = " + this.getShelfWorldPosition())
  }

  // =====================================================================================
  // Public API (used by the scene and by LEAF tests)
  // =====================================================================================
  getPlacedCount(): number { return this.placedCount }
  getMistakes(): number { return this.mistakes }
  getOverhangMistakes(): number { return this.overhangMistakes }
  getGapMistakes(): number { return this.gapMistakes }
  /** Index into the order of the case due now (ORDER.length when complete). */
  getNextIndex(): number { return this.nextIndex }
  isComplete(): boolean { return this.complete }
  isGhostVisible(): boolean { return this.ghost.enabled }
  getGhostTagText(): string { return this.ghostTag.isVisible() ? this.ghostTagString : "" }
  isGhostTagVisible(): boolean { return this.ghostTag.isVisible() }
  /** Ghost box size in Pallet axes (x across, z depth). */
  getGhostSize(): vec3 { return this.ghostFill.getTransform().getLocalScale() }
  getTipText(): string { return this.tipString }
  /** "overhang" | "gap" | "layer" | "" */
  getTipKind(): string { return this.tipKind }
  isTipVisible(): boolean { return this.tipText.isVisible() }
  isCompletionVisible(): boolean { return this.completionCard.isVisible() }
  getCompletionText(): string { return this.completionString }
  getCounterText(): string { return this.counter.getText() }
  isArrowVisible(): boolean { return this.arrowVisible }
  isNextCaseInView(): boolean { return this.nextInView }
  getCaseCount(): number { return this.cases.length }
  getCaseName(i: number): string { return this.cases[i] ? this.cases[i].so.name : "" }
  isCasePlaced(i: number): boolean { return !!this.cases[i] && this.cases[i].placed }
  isCaseReturning(i: number): boolean { return !!this.cases[i] && this.cases[i].returning }
  isCaseGlowing(i: number): boolean { return !!this.cases[i] && this.cases[i].glow.enabled }
  isCaseShown(i: number): boolean { return !!this.cases[i] && this.cases[i].so.enabled }
  isCaseInteractable(i: number): boolean { return !!this.cases[i] && this.cases[i].interactable.enabled }
  /** Queue position of case i on the pick face (0 = due now), or -1 if placed / not in the queue. */
  getQueuePosition(i: number): number {
    if (!this.cases[i] || this.cases[i].placed) return -1
    const q = i - this.nextIndex
    return q >= 0 && q < QUEUE_SIZE ? q : -1
  }
  getQueueSize(): number { return QUEUE_SIZE }
  getQueueSlotWorldPosition(q: number, i: number): vec3 { return this.queueHome(q, this.cases[i].spec) }
  getGrabbedIndex(): number { return this.grabbedIndex }
  getGhostWorldPosition(): vec3 { return this.ghost.getTransform().getWorldPosition() }
  /** Where case i snaps to on the pallet (centre of the case). */
  getSlotWorldPosition(i: number): vec3 { return this.palletT.getWorldTransform().multiplyPoint(PLAN[i].center) }
  getSlotWorldRotation(i: number): quat { return this.plannedRotation(i) }
  isSlotTurned(i: number): boolean { return PLAN[i].turned }
  getSlotLayer(i: number): number { return PLAN[i].layer }
  getCaseWorldPosition(i: number): vec3 { return this.cases[i].so.getTransform().getWorldPosition() }
  getCaseWorldRotation(i: number): quat { return this.cases[i].so.getTransform().getWorldRotation() }
  getCaseHomePosition(i: number): vec3 { return this.cases[i].home }
  getPalletWorldPosition(): vec3 { return this.palletT.getWorldPosition() }
  getPalletWorldTransform(): mat4 { return this.palletT.getWorldTransform() }
  getShelfWorldPosition(): vec3 { return this.shelfBay.getTransform().getWorldPosition() }
  getCameraWorldPosition(): vec3 { return WorldCameraFinderProvider.getInstance().getTransform().getWorldPosition() }
  /** Floor height (world y): the pallet root sits on the floor. */
  getFloorWorldY(): number { return this.palletT.getWorldPosition().y }
  getHeightLimitWorldY(): number { return this.heightLimit.getTransform().getWorldPosition().y }
  isHeightLimitVisible(): boolean { return this.heightLimit.enabled && this.heightLimit.isEnabledInHierarchy }
  /** Top of the placed stack above the floor (cm). */
  getStackTopCm(): number { return this.stackTop() }

  /** Test hook: same code path as a real SIK grab. */
  simulateGrab(caseIndex: number): void {
    this.handleGrab(caseIndex)
  }

  /** Test hook: moves the case to worldPos, then runs the same code path as a real SIK release. */
  simulateRelease(caseIndex: number, worldPos: vec3): void {
    const c = this.cases[caseIndex]
    if (!c) return
    if (!c.placed) c.so.getTransform().setWorldPosition(worldPos)
    this.handleRelease(caseIndex, worldPos)
  }

  /** Test hook: same path as pinching the Reset button. */
  pressReset(): void {
    this.resetButton.press()
  }

  /** Clears the pallet and restarts the order: the first 4 cases on the pick face. */
  reset(): void {
    for (const c of this.cases) {
      c.placed = false
      c.grabbed = false
      c.returning = false
      c.hovered = false
      c.so.getTransform().setWorldRotation(quat.quatIdentity())
      this.tint(c, 0)
    }
    this.nextIndex = 0
    this.placedCount = 0
    this.mistakes = 0
    this.overhangMistakes = 0
    this.gapMistakes = 0
    this.complete = false
    this.grabbedIndex = -1
    this.startTime = -1
    this.finishTime = -1
    this.completionString = ""
    this.ghostTagString = ""
    this.hideTip()
    this.ghost.enabled = false
    this.ghostTag.setVisible(false)
    this.completionCard.setVisible(false)
    this.wasOutOfView = false
    this.layoutQueue(false)
    this.updateCounter()
    this.updateStackFollowers()
    this.log("reset")
  }

  // =====================================================================================
  // Rules
  // =====================================================================================
  private handleGrab(i: number): void {
    const c = this.cases[i]
    if (!c || c.placed || this.complete || i !== this.nextIndex) return
    c.grabbed = true
    c.returning = false
    this.grabbedIndex = i
    if (this.startTime < 0) this.startTime = getTime()
    this.showGhostFor(i)
    this.updateGlow()
    this.log("grab " + c.so.name + " (ghost shown, layer " + PLAN[i].layer + (PLAN[i].turned ? ", turned 90" : "") + ")")
  }

  private handleRelease(i: number, worldPos: vec3): void {
    const c = this.cases[i]
    if (!c || c.placed) return
    c.grabbed = false
    if (this.grabbedIndex === i) this.grabbedIndex = -1
    this.hideGhost()

    if (this.complete || i !== this.nextIndex) {
      this.sendHome(c)
      this.updateGlow()
      return
    }

    const local = this.palletT.getInvertedWorldTransform().multiplyPoint(worldPos)
    const halfPallet = PALLET_SIZE_CM.x / 2
    const reach = halfPallet + OFF_PALLET_MARGIN_CM
    const onPallet = Math.abs(local.x) <= reach && Math.abs(local.z) <= reach && local.y >= -20 && local.y <= 250

    const slot = PLAN[i].center
    const dx = local.x - slot.x
    const dz = local.z - slot.z
    const dy = local.y - slot.y
    const horiz = Math.sqrt(dx * dx + dz * dz)
    if (horiz <= this.snapDistanceCm && dy >= -this.snapDistanceCm && dy <= Math.max(this.snapDistanceCm, this.dropHeightAllowanceCm)) {
      this.place(c)
    } else if (onPallet) {
      // Would any part of the case (planned orientation, centred on the drop point) hang over the edge?
      const fp = footprint(c.spec, PLAN[i].turned)
      const over = Math.max(Math.abs(local.x) + fp.x / 2, Math.abs(local.z) + fp.y / 2) - halfPallet
      if (over > OVERHANG_TOLERANCE_CM) this.mistake(c, "overhang", TIP_OVERHANG)
      else this.mistake(c, "gap", TIP_GAP)
    } else {
      this.log("released " + c.so.name + " off the pallet: back to the pick face, no mistake")
      this.sendHome(c)
    }
    this.updateGlow()
  }

  private place(c: CaseState): void {
    const i = c.index
    const t = c.so.getTransform()
    t.setWorldPosition(this.getSlotWorldPosition(i))
    t.setWorldRotation(this.plannedRotation(i))
    c.placed = true
    c.returning = false
    this.tint(c, 0)
    this.placedCount++
    this.nextIndex++
    this.play("snap")
    this.log("placed " + c.so.name + " -> " + this.placedCount + "/" + this.cases.length)
    if (this.nextIndex >= this.cases.length) {
      this.finish()
    } else if (isLastOfLayer(i)) {
      this.showTip("layer", layerDoneText(PLAN[i].layer), this.noteColor)
    }
    this.layoutQueue(true)
    this.updateCounter()
    this.updateStackFollowers()
  }

  private mistake(c: CaseState, kind: string, tip: string): void {
    this.mistakes++
    if (kind === "overhang") this.overhangMistakes++
    else if (kind === "gap") this.gapMistakes++
    this.showTip(kind, tip, this.tipColor)
    this.play("mistake")
    this.log("mistake #" + this.mistakes + " (" + c.so.name + "): " + tip.replace(/\n/g, " "))
    this.sendHome(c)
  }

  private showTip(kind: string, msg: string, color: vec4): void {
    this.tipKind = kind
    this.tipString = msg
    this.tipText.setText(msg)
    this.tipText.setTextColor(color)
    this.tipText.setVisible(true)
    this.tipHideAt = getTime() + this.tipDurationSec
  }

  private hideTip(): void {
    this.tipHideAt = -1
    this.tipKind = ""
    this.tipString = ""
    this.tipText.setVisible(false)
  }

  // " (2 overhang · 1 gap)" so the learner sees which rule they broke; empty when there were none.
  private mistakeBreakdown(): string {
    const parts: string[] = []
    if (this.overhangMistakes > 0) parts.push(this.overhangMistakes + " overhang")
    if (this.gapMistakes > 0) parts.push(this.gapMistakes + " gap")
    return parts.length > 0 ? " (" + parts.join(" · ") + ")" : ""
  }

  private finish(): void {
    this.complete = true
    this.finishTime = getTime()
    const secs = Math.max(0, Math.round(this.finishTime - (this.startTime < 0 ? this.finishTime : this.startTime)))
    const mm = Math.floor(secs / 60)
    const ss = secs % 60
    const time = mm + ":" + (ss < 10 ? "0" : "") + ss
    const height = Math.round(this.stackTop())
    this.completionString = "Pallet done! " + this.cases.length + " cases · " + LAYER_COUNT + " layers · " + height + " cm\n" +
      "Time " + time + " · Mistakes " + this.mistakes + this.mistakeBreakdown() + "\nWrap and label the pallet."
    this.completionCard.setText(this.completionString)
    // Above the 180 cm line, not across it, and larger so it reads from where the picker stands.
    const cardT = this.completionCard.sceneObject.getTransform()
    cardT.setLocalPosition(new vec3(0, Math.max(this.stackTop() + 24, HEIGHT_LIMIT_CM + 30), 20))
    cardT.setLocalScale(new vec3(1.5, 1.5, 1.5))
    this.completionCard.setVisible(true)
    this.hideTip()
    this.arrowVisible = false
    this.offViewArrow.enabled = false
    this.play("complete")
  }

  private sendHome(c: CaseState): void {
    c.returning = true
    c.returnT = 0
    c.returnFrom = c.so.getTransform().getWorldPosition()
  }

  private showGhostFor(i: number): void {
    const spec = this.cases[i].spec
    const slot = PLAN[i]
    const size = plannedSize(spec, slot.turned)
    this.ghost.getTransform().setLocalPosition(slot.center)
    this.ghostFill.getTransform().setLocalScale(size)
    BoxFactory.layoutWireBox(this.ghostWire, size.add(new vec3(0.6, 0.6, 0.6)), 0.8)
    this.ghost.enabled = true
    this.ghostTagString = ghostTagText(i)
    this.ghostTag.setText(this.ghostTagString)
    this.ghostTag.sceneObject.getTransform().setLocalPosition(
      new vec3(slot.center.x, slot.center.y + size.y / 2 + 7, slot.center.z + size.z / 2 + 3))
    this.ghostTag.setVisible(true)
  }

  private hideGhost(): void {
    this.ghost.enabled = false
    this.ghostTag.setVisible(false)
  }

  /** Pallet rotation, plus 90 degrees about up when the slot is turned. */
  private plannedRotation(i: number): quat {
    const r = this.palletT.getWorldRotation()
    return PLAN[i].turned ? r.multiply(quat.angleAxis(Math.PI / 2, vec3.up())) : r
  }

  private stackTop(): number {
    if (this.placedCount === 0) return PALLET_DECK_Y
    const k = this.placedCount - 1
    return PLAN[k].center.y + this.cases[k].spec.size.y / 2
  }

  /** World position of queue slot q (0 = due now, nearest the pallet) on the lower shelf. */
  private queueHome(q: number, spec: CaseSpec): vec3 {
    // front-aligned: every case's pallet-facing side sits 2 cm behind the shelf's front edge
    const local = new vec3(SHELF_FRONT_X + 2 + spec.size.x / 2, SHELF_TOP_Y + spec.size.y / 2, QUEUE_FRONT_Z + q * QUEUE_PITCH_Z)
    return this.shelfBay.getTransform().getWorldTransform().multiplyPoint(local)
  }

  /**
   * Shows the next QUEUE_SIZE not-yet-placed cases on the pick face and hides the rest.
   * animate = true: cases already on the shelf slide up to their new slot; a case entering the
   * queue appears at the back.
   */
  private layoutQueue(animate: boolean): void {
    for (const c of this.cases) {
      if (c.placed) {
        c.so.enabled = true
        continue
      }
      const q = c.index - this.nextIndex
      const inQueue = q >= 0 && q < QUEUE_SIZE
      const wasShown = c.so.enabled
      c.so.enabled = inQueue
      if (!inQueue) {
        c.returning = false
        continue
      }
      c.home = this.queueHome(q, c.spec)
      if (animate && wasShown) {
        if (!c.grabbed) this.sendHome(c)
      } else {
        c.returning = false
        c.so.getTransform().setWorldPosition(c.home)
        c.so.getTransform().setWorldRotation(quat.quatIdentity())
      }
    }
    this.updateInteractivity()
    this.updateGlow()
  }

  /** Only the case due now can be grabbed. */
  private updateInteractivity(): void {
    for (const c of this.cases) {
      const on = !this.complete && !c.placed && c.index === this.nextIndex
      c.interactable.enabled = on
      c.manip.enabled = on
      if (!on && c.hovered) this.setHover(c.index, false)
    }
  }

  private updateCounter(): void {
    const layer = PLAN[Math.min(this.nextIndex, PLAN.length - 1)].layer
    this.counter.setText("Layer " + layer + " · " + this.placedCount + " / " + this.cases.length)
  }

  /** Keeps the tip/note and the off-view arrow just above the current stack top. */
  private updateStackFollowers(): void {
    const top = this.stackTop()
    this.tipText.sceneObject.getTransform().setLocalPosition(new vec3(0, Math.max(75, top + 28), top > 50 ? 30 : 62))
    this.offViewArrow.getTransform().setLocalPosition(new vec3(35, top + 3, 52))
  }

  private updateGlow(): void {
    for (const c of this.cases) {
      c.glow.enabled = !this.complete && c.index === this.nextIndex && !c.grabbed && !c.placed
    }
  }

  private setHover(i: number, on: boolean): void {
    const c = this.cases[i]
    if (!c || c.placed) return
    c.hovered = on
    this.tint(c, on ? 0.4 : 0)
  }

  /** Every body material of the case at its colour lightened by k (0 = own colour). */
  private tint(c: CaseState, k: number): void {
    c.bodyMats.forEach((m, j) => {
      const col = c.bodyColors[j]
      m.mainPass.baseColor = new vec4(col.x + (1 - col.x) * k, col.y + (1 - col.y) * k, col.z + (1 - col.z) * k, col.w)
    })
  }

  // =====================================================================================
  // Per-frame: slide-back / queue slide, tip timeout, glow pulse, off-view arrow + chime
  // =====================================================================================
  private onUpdate(): void {
    if (!this.ready) return
    const now = getTime()
    const dt = getDeltaTime()

    for (const c of this.cases) {
      if (!c.returning) continue
      c.returnT = Math.min(1, c.returnT + dt / this.returnDuration)
      const e = 1 - Math.pow(1 - c.returnT, 3)
      c.so.getTransform().setWorldPosition(vec3.lerp(c.returnFrom, c.home, e))
      if (c.returnT >= 1) {
        c.returning = false
        c.so.getTransform().setWorldRotation(quat.quatIdentity())
      }
    }

    if (this.tipHideAt > 0 && now >= this.tipHideAt) {
      this.hideTip()
    }

    const pulse = 0.65 + 0.35 * Math.sin(now * 3)
    for (const c of this.cases) {
      if (c.glow.enabled) {
        c.glowMat.mainPass.baseColor = new vec4(this.glowColor.x, this.glowColor.y, this.glowColor.z, this.glowColor.w * pulse)
      }
    }

    this.updateOffView(now)
  }

  private updateOffView(now: number): void {
    if (this.complete || this.nextIndex >= this.cases.length) {
      this.arrowVisible = false
      this.offViewArrow.enabled = false
      return
    }
    const next = this.cases[this.nextIndex]
    const target = next.so.getTransform().getWorldPosition()
    const cam = WorldCameraFinderProvider.getInstance()
    this.nextInView = cam.inFoV(target)
    const show = !this.nextInView && this.grabbedIndex < 0
    this.arrowVisible = show
    this.offViewArrow.enabled = show
    if (show) {
      const from = this.offViewArrow.getTransform().getWorldPosition()
      const dx = target.x - from.x
      const dz = target.z - from.z
      const yaw = Math.atan2(-dz, dx) // arrow geometry points along local +X
      this.offViewArrow.getTransform().setWorldRotation(quat.angleAxis(yaw, vec3.up()))
      if (!this.wasOutOfView && now - this.lastChimeAt >= CHIME_COOLDOWN_SEC) {
        this.lastChimeAt = now
        this.play("chime")
      }
    }
    this.wasOutOfView = show
  }

  // =====================================================================================
  // Build (placeholder visuals on authored roots)
  // =====================================================================================
  /** Puts the floor (work-area root) eyeHeightCm below the camera's current height. */
  private alignFloorToCamera(): void {
    const root = this.sceneObject.getParent()
    if (!root) return
    const cam = WorldCameraFinderProvider.getInstance()
    if (!cam) return
    const camY = cam.getTransform().getWorldPosition().y
    const t = root.getTransform()
    const p = t.getWorldPosition()
    t.setWorldPosition(new vec3(p.x, camY - this.eyeHeightCm, p.z))
    this.log("floor aligned: camera y = " + camY + ", floor y = " + (camY - this.eyeHeightCm))
  }

