              center: new vec3(x + fp.x / 2, tierBottom + order[k].size.y / 2, z + r.depth / 2),
              layer, turned: order[k].turned, zone, tier: ti, row: ri, col: ci,
            }
            x += fp.x
          })
          z += r.depth
        })
        tierBottom += t.height
      })
