      if (step > MAX_STEP_CM + 0.01) print("[StackRightPickList] ERROR: layer " + layer + " step is " + step + " cm after " + order[k].name + ", max " + MAX_STEP_CM)
    }
    bottom = layerTop
  }
  return plan
}

/** True when another case of the same layer (order indices from..to-1) sits directly on case k. */
function hasCaseOnTop(plan: PlannedSlot[], order: CaseSpec[], k: number, from: number, to: number): boolean {
  const top = plan[k].center.y + order[k].size.y / 2
  const fk = footprint(order[k], plan[k].turned)
  for (let j = from; j < to; j++) {
    if (j === k || !plan[j]) continue
    if (Math.abs(plan[j].center.y - order[j].size.y / 2 - top) > 0.01) continue
    const fj = footprint(order[j], plan[j].turned)
    const ox = Math.min(plan[k].center.x + fk.x / 2, plan[j].center.x + fj.x / 2) - Math.max(plan[k].center.x - fk.x / 2, plan[j].center.x - fj.x / 2)
    const oz = Math.min(plan[k].center.z + fk.y / 2, plan[j].center.z + fj.y / 2) - Math.max(plan[k].center.z - fk.y / 2, plan[j].center.z - fj.y / 2)
    if (ox > 0.01 && oz > 0.01) return true
  }
  return false
}

/**
 * Height difference (cm) between the highest and lowest zone of case k's layer right after case k
 * is placed, building in order. A zone with nothing placed yet counts at the layer's bottom.
 * 0 for a layer with one zone.
 */
function stepOf(plan: PlannedSlot[], order: CaseSpec[], k: number): number {
  const layer = order[k].layer
  let first = k
  while (first > 0 && order[first - 1].layer === layer) first--
  let last = k
  while (last + 1 < order.length && order[last + 1].layer === layer) last++
  const bottom = plan[first].center.y - order[first].size.y / 2 - plan[first].tier * 0 // tier 0 of the first line sits on the layer below
  const tops: {[zone: string]: number} = {}
  for (let j = first; j <= last; j++) if (tops[order[j].zone] === undefined) tops[order[j].zone] = bottom
  for (let j = first; j <= k; j++) tops[order[j].zone] = Math.max(tops[order[j].zone], plan[j].center.y + order[j].size.y / 2)
  let hi = -1e9, lo = 1e9
  for (const z in tops) { hi = Math.max(hi, tops[z]); lo = Math.min(lo, tops[z]) }
  return hi - lo
}

