    this.check("DC6", "all 31 placed, counter '" + c.getCounterText() + "'", c.isComplete() && c.getCounterText() === "Layer 5 · 31 / 31")
    this.check("DC6", "stack top " + c.getStackTopCm().toFixed(1) + " cm (127), under the 180 cm limit",
