    expect(c.getGhostTagText()).toBe("Layer 4 · 21 of 31 · 10 kg")
    c.simulateRelease(20, c.getSlotWorldPosition(20))
    for (let i = 21; i < 28; i++) dropOnSlot(c, i)
    await sleep(100)

