    c.simulateGrab(28)
    expect(c.isSlotTurned(28)).toBe(false)
    expect(Math.abs(c.getGhostSize().x - 112) < 0.1).toBe(true)
    expect(c.getGhostTagText()).toBe("Layer 5 · 29 of 31 · 3 kg")
  }
}
